-- Expand only; old records and manifests are not rewritten.
CREATE TABLE IF NOT EXISTS treasury_operations(workspace_id uuid NOT NULL,id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('allowance','payout','invalidation')),manifest jsonb NOT NULL,state text NOT NULL DEFAULT 'frozen',created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS operation_exact_intent ON treasury_operations(workspace_id,(manifest->>'safeTxHash'));
ALTER TABLE batches ADD COLUMN IF NOT EXISTS operation_id uuid;
CREATE TABLE IF NOT EXISTS treasury_signatures(workspace_id uuid NOT NULL,operation_id uuid NOT NULL,owner text NOT NULL,signature text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,operation_id,owner),FOREIGN KEY(workspace_id,operation_id) REFERENCES treasury_operations(workspace_id,id));
CREATE TABLE IF NOT EXISTS treasury_attempts(workspace_id uuid NOT NULL,id uuid NOT NULL,operation_id uuid NOT NULL,sender text NOT NULL,sender_nonce text NOT NULL,transaction_data text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(workspace_id,id),FOREIGN KEY(workspace_id,operation_id) REFERENCES treasury_operations(workspace_id,id));
CREATE TABLE IF NOT EXISTS treasury_observations(id bigserial PRIMARY KEY,workspace_id uuid NOT NULL,attempt_id uuid NOT NULL,kind text NOT NULL,transaction_hash text,at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,attempt_id) REFERENCES treasury_attempts(workspace_id,id));
CREATE TABLE IF NOT EXISTS treasury_reports(id bigserial PRIMARY KEY,workspace_id uuid NOT NULL,operation_id uuid NOT NULL,report jsonb NOT NULL,at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,operation_id) REFERENCES treasury_operations(workspace_id,id));
CREATE TABLE IF NOT EXISTS treasury_settlements(workspace_id uuid NOT NULL,payable_id uuid NOT NULL,operation_id uuid NOT NULL,report_id bigint NOT NULL REFERENCES treasury_reports(id),state text NOT NULL CHECK(state IN ('verified','retracted')),PRIMARY KEY(workspace_id,payable_id),FOREIGN KEY(workspace_id,payable_id) REFERENCES payables(workspace_id,id),FOREIGN KEY(workspace_id,operation_id) REFERENCES treasury_operations(workspace_id,id));
CREATE TABLE IF NOT EXISTS treasury_checkpoints(chain_key text PRIMARY KEY,number bigint NOT NULL,hash text NOT NULL,paused boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS treasury_headers(chain_key text NOT NULL,number bigint NOT NULL,hash text NOT NULL,parent_hash text NOT NULL,canonical boolean NOT NULL,PRIMARY KEY(chain_key,hash));
CREATE UNIQUE INDEX IF NOT EXISTS treasury_canonical_height ON treasury_headers(chain_key,number) WHERE canonical;
CREATE OR REPLACE FUNCTION treasury_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'IMMUTABLE_AUTHORIZATION_EVIDENCE'; END $$;
CREATE OR REPLACE FUNCTION treasury_manifest_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.manifest IS DISTINCT FROM OLD.manifest OR NEW.kind IS DISTINCT FROM OLD.kind OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id OR NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'IMMUTABLE_INTENT'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS frozen_operation_immutable ON treasury_operations;
CREATE TRIGGER frozen_operation_immutable BEFORE UPDATE ON treasury_operations FOR EACH ROW EXECUTE FUNCTION treasury_manifest_immutable();
DROP TRIGGER IF EXISTS frozen_batch_immutable ON batches;
CREATE TRIGGER frozen_batch_immutable BEFORE UPDATE OF manifest ON batches FOR EACH ROW EXECUTE FUNCTION treasury_immutable();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['treasury_attempts','treasury_observations','treasury_reports','treasury_signatures'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS immutable_evidence ON %I',t); EXECUTE format('CREATE TRIGGER immutable_evidence BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION treasury_immutable()',t); END LOOP; END $$;
